-- BEGIN COMPONENT gate-session
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_gate_session_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.gate-session.v3')
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_gate_session_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.gate-session.v3');

CREATE TABLE IF NOT EXISTS gate_session_heads (
    session_id TEXT PRIMARY KEY
        CHECK (length(session_id) BETWEEN 1 AND 128),
    tenant_id TEXT NOT NULL
        CHECK (length(tenant_id) BETWEEN 1 AND 128),
    repository_id TEXT NOT NULL
        CHECK (length(repository_id) BETWEEN 1 AND 128),
    principal_id TEXT NOT NULL
        CHECK (length(principal_id) BETWEEN 1 AND 128),
    agent_client_id TEXT NOT NULL
        CHECK (length(agent_client_id) BETWEEN 1 AND 128),
    trace_id TEXT NOT NULL
        CHECK (length(trace_id) BETWEEN 1 AND 128),
    run_id TEXT NOT NULL
        CHECK (length(run_id) BETWEEN 1 AND 128),
    request_fingerprint TEXT NOT NULL
        CHECK (
            length(request_fingerprint) = 71
            AND substr(request_fingerprint, 1, 7) = 'sha256:'
            AND substr(request_fingerprint, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    idempotency_key TEXT NOT NULL
        CHECK (length(idempotency_key) BETWEEN 1 AND 512),
    current_version INTEGER NOT NULL CHECK (current_version >= 1),
    UNIQUE (
        tenant_id,
        repository_id,
        principal_id,
        agent_client_id,
        idempotency_key
    )
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS gate_session_revisions (
    session_id TEXT NOT NULL,
    version INTEGER NOT NULL CHECK (version >= 1),
    status TEXT NOT NULL CHECK (
        status IN (
            'created',
            'prepared',
            'awaiting_decision',
            'decided',
            'finalized',
            'executing',
            'completed',
            'canceled',
            'expired',
            'abandoned'
        )
    ),
    updated_at TEXT NOT NULL CHECK (length(updated_at) BETWEEN 20 AND 32),
    expires_at TEXT NOT NULL CHECK (length(expires_at) BETWEEN 20 AND 32),
    lease_expires_at TEXT
        CHECK (
            lease_expires_at IS NULL
            OR length(lease_expires_at) BETWEEN 20 AND 32
        ),
    payload TEXT NOT NULL CHECK (
        length(CAST(payload AS BLOB)) > 0
        AND length(CAST(payload AS BLOB)) <= 1048576
    ),
    PRIMARY KEY (session_id, version),
    FOREIGN KEY (session_id)
        REFERENCES gate_session_heads (session_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CHECK (
        (
            status IN (
                'prepared',
                'awaiting_decision',
                'decided',
                'finalized',
                'executing'
            )
            AND lease_expires_at IS NOT NULL
        )
        OR (
            status NOT IN (
                'prepared',
                'awaiting_decision',
                'decided',
                'finalized',
                'executing'
            )
            AND lease_expires_at IS NULL
        )
    )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS gate_session_revisions_due
ON gate_session_revisions (status, expires_at, lease_expires_at, session_id)
WHERE status IN (
    'prepared',
    'awaiting_decision',
    'decided',
    'finalized',
    'executing'
);

CREATE TRIGGER IF NOT EXISTS gate_session_heads_identity_immutable
BEFORE UPDATE ON gate_session_heads
FOR EACH ROW
WHEN
    NEW.session_id <> OLD.session_id
    OR NEW.tenant_id <> OLD.tenant_id
    OR NEW.repository_id <> OLD.repository_id
    OR NEW.principal_id <> OLD.principal_id
    OR NEW.agent_client_id <> OLD.agent_client_id
    OR NEW.trace_id <> OLD.trace_id
    OR NEW.run_id <> OLD.run_id
    OR NEW.request_fingerprint <> OLD.request_fingerprint
    OR NEW.idempotency_key <> OLD.idempotency_key
BEGIN
    SELECT RAISE(ABORT, 'GateSession identity is immutable');
END;

CREATE TRIGGER IF NOT EXISTS gate_session_heads_version_forward
BEFORE UPDATE OF current_version ON gate_session_heads
FOR EACH ROW
WHEN
    NEW.current_version <> OLD.current_version + 1
    OR NOT EXISTS (
        SELECT 1
        FROM gate_session_revisions AS revision
        WHERE revision.session_id = OLD.session_id
          AND revision.version = NEW.current_version
    )
BEGIN
    SELECT RAISE(ABORT, 'GateSession head must advance by one revision');
END;

CREATE TRIGGER IF NOT EXISTS gate_session_heads_immutable_delete
BEFORE DELETE ON gate_session_heads
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'GateSession head is immutable');
END;

CREATE TRIGGER IF NOT EXISTS gate_session_revisions_immutable_update
BEFORE UPDATE ON gate_session_revisions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'GateSession revision is immutable');
END;

CREATE TRIGGER IF NOT EXISTS gate_session_revisions_validate_insert
BEFORE INSERT ON gate_session_revisions
FOR EACH ROW
WHEN
    NEW.version <> COALESCE(
        (
            SELECT MAX(previous.version) + 1
            FROM gate_session_revisions AS previous
            WHERE previous.session_id = NEW.session_id
        ),
        1
    )
    OR (
        NEW.version = 1
        AND NEW.status <> 'created'
    )
    OR (
        NEW.version > 1
        AND NOT EXISTS (
            SELECT 1
            FROM gate_session_revisions AS previous
            JOIN gate_session_heads AS head
              ON head.session_id = previous.session_id
            WHERE previous.session_id = NEW.session_id
              AND previous.version = NEW.version - 1
              AND head.current_version = previous.version
              AND previous.updated_at < NEW.updated_at
              AND previous.expires_at = NEW.expires_at
              AND (
                  (previous.status = 'created'
                      AND NEW.status IN ('prepared', 'canceled'))
                  OR (previous.status = 'prepared'
                      AND NEW.status IN (
                          'awaiting_decision',
                          'canceled',
                          'expired'
                      ))
                  OR (previous.status = 'awaiting_decision'
                      AND NEW.status IN (
                          'decided',
                          'canceled',
                          'expired'
                      ))
                  OR (previous.status = 'decided'
                      AND NEW.status = 'finalized')
                  OR (previous.status = 'finalized'
                      AND NEW.status = 'executing')
                  OR (previous.status = 'executing'
                      AND NEW.status IN ('completed', 'abandoned'))
                  OR (
                      previous.status IN (
                          'prepared',
                          'awaiting_decision',
                          'decided',
                          'finalized',
                          'executing'
                      )
                      AND NEW.status = previous.status
                  )
              )
        )
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid GateSession revision transition');
END;

CREATE TRIGGER IF NOT EXISTS gate_session_revisions_immutable_delete
BEFORE DELETE ON gate_session_revisions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'GateSession revision is immutable');
END;
-- END COMPONENT gate-session

-- BEGIN COMPONENT gate-evidence
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_gate_evidence_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1)
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_gate_evidence_schema (
    singleton,
    schema_version
) VALUES (1, 1);

CREATE TABLE IF NOT EXISTS v3_retrieval_snapshots (
    snapshot_id TEXT PRIMARY KEY
        CHECK (
            length(snapshot_id) = 90
            AND substr(snapshot_id, 1, 26) = 'retrieval_snapshot_sha256_'
            AND substr(snapshot_id, 27) NOT GLOB '*[^0-9a-f]*'
        ),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    authorization_event_id TEXT NOT NULL
        CHECK (
            length(authorization_event_id) = 77
            AND substr(authorization_event_id, 1, 13) = 'authz_sha256_'
            AND substr(authorization_event_id, 14) NOT GLOB '*[^0-9a-f]*'
        ),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_retrieval_snapshots_session
ON v3_retrieval_snapshots(session_id, authorization_event_id);

CREATE TABLE IF NOT EXISTS v3_system_gate_evaluations (
    evaluation_id TEXT PRIMARY KEY
        CHECK (
            length(evaluation_id) = 83
            AND substr(evaluation_id, 1, 19) = 'system_gate_sha256_'
            AND substr(evaluation_id, 20) NOT GLOB '*[^0-9a-f]*'
        ),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    retrieval_snapshot_id TEXT NOT NULL UNIQUE
        REFERENCES v3_retrieval_snapshots(snapshot_id),
    authorization_event_id TEXT NOT NULL
        CHECK (
            length(authorization_event_id) = 77
            AND substr(authorization_event_id, 1, 13) = 'authz_sha256_'
            AND substr(authorization_event_id, 14) NOT GLOB '*[^0-9a-f]*'
        ),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_system_gate_evaluations_session
ON v3_system_gate_evaluations(session_id, authorization_event_id);

CREATE TRIGGER IF NOT EXISTS v3_system_gate_evaluations_parent_match
BEFORE INSERT ON v3_system_gate_evaluations
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_retrieval_snapshots AS snapshot
    WHERE snapshot.snapshot_id = NEW.retrieval_snapshot_id
      AND snapshot.session_id = NEW.session_id
      AND snapshot.authorization_event_id = NEW.authorization_event_id
)
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 System Gate evaluation parent scope does not match'
    );
END;

CREATE TRIGGER IF NOT EXISTS v3_retrieval_snapshots_immutable_update
BEFORE UPDATE ON v3_retrieval_snapshots
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 retrieval snapshots are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_retrieval_snapshots_immutable_delete
BEFORE DELETE ON v3_retrieval_snapshots
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 retrieval snapshots are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_system_gate_evaluations_immutable_update
BEFORE UPDATE ON v3_system_gate_evaluations
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 System Gate evaluations are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_system_gate_evaluations_immutable_delete
BEFORE DELETE ON v3_system_gate_evaluations
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 System Gate evaluations are immutable');
END;
-- END COMPONENT gate-evidence

-- BEGIN COMPONENT semantic-gate
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_semantic_gate_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.semantic-gate-attempt.v3')
) WITHOUT ROWID;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_schema_requires_evidence
BEFORE INSERT ON trace_backed_memory_v3_semantic_gate_schema
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM trace_backed_memory_v3_gate_evidence_schema
    WHERE singleton = 1 AND schema_version = 1
)
BEGIN
    SELECT RAISE(
        ABORT,
        'SQLite semantic Gate v3 requires gate evidence v3'
    );
END;

INSERT OR IGNORE INTO trace_backed_memory_v3_semantic_gate_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.semantic-gate-attempt.v3');

CREATE TABLE IF NOT EXISTS v3_semantic_gate_attempt_heads (
    system_gate_evaluation_id TEXT PRIMARY KEY
        REFERENCES v3_system_gate_evaluations(evaluation_id),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    retrieval_snapshot_id TEXT NOT NULL
        REFERENCES v3_retrieval_snapshots(snapshot_id),
    current_sequence INTEGER NOT NULL
        CHECK (current_sequence >= 0 AND current_sequence <= 100),
    current_attempt_id TEXT,
    CHECK (
        (current_sequence = 0 AND current_attempt_id IS NULL)
        OR (current_sequence > 0 AND current_attempt_id IS NOT NULL)
    ),
    FOREIGN KEY (system_gate_evaluation_id, current_attempt_id)
        REFERENCES v3_semantic_gate_attempts (
            system_gate_evaluation_id,
            attempt_id
        )
        DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_semantic_gate_attempts (
    attempt_id TEXT PRIMARY KEY
        CHECK (
            length(attempt_id) = 88
            AND substr(attempt_id, 1, 24) = 'semantic_attempt_sha256_'
            AND substr(attempt_id, 25) NOT GLOB '*[^0-9a-f]*'
        ),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    retrieval_snapshot_id TEXT NOT NULL
        REFERENCES v3_retrieval_snapshots(snapshot_id),
    system_gate_evaluation_id TEXT NOT NULL
        REFERENCES v3_system_gate_evaluations(evaluation_id),
    sequence INTEGER NOT NULL CHECK (sequence BETWEEN 1 AND 100),
    previous_attempt_id TEXT,
    status TEXT NOT NULL CHECK (status IN ('succeeded', 'failed')),
    started_at TEXT NOT NULL
        CHECK (length(started_at) BETWEEN 20 AND 32),
    finished_at TEXT NOT NULL
        CHECK (length(finished_at) BETWEEN 20 AND 32),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        ),
    UNIQUE (system_gate_evaluation_id, sequence),
    UNIQUE (system_gate_evaluation_id, attempt_id),
    FOREIGN KEY (system_gate_evaluation_id, previous_attempt_id)
        REFERENCES v3_semantic_gate_attempts (
            system_gate_evaluation_id,
            attempt_id
        )
        DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_semantic_gate_attempts_session
ON v3_semantic_gate_attempts(session_id, system_gate_evaluation_id, sequence);

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_heads_parent_scope
BEFORE INSERT ON v3_semantic_gate_attempt_heads
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_system_gate_evaluations AS evaluation
    JOIN v3_retrieval_snapshots AS snapshot
      ON snapshot.snapshot_id = evaluation.retrieval_snapshot_id
    WHERE evaluation.evaluation_id = NEW.system_gate_evaluation_id
      AND evaluation.session_id = NEW.session_id
      AND evaluation.retrieval_snapshot_id = NEW.retrieval_snapshot_id
      AND snapshot.session_id = NEW.session_id
)
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 semantic Gate head parent scope does not match'
    );
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_heads_identity_immutable
BEFORE UPDATE ON v3_semantic_gate_attempt_heads
FOR EACH ROW
WHEN NEW.system_gate_evaluation_id <> OLD.system_gate_evaluation_id
  OR NEW.session_id <> OLD.session_id
  OR NEW.retrieval_snapshot_id <> OLD.retrieval_snapshot_id
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate head identity is immutable');
END;

CREATE TRIGGER IF NOT EXISTS
v3_semantic_gate_heads_immutable_insert_conflict
BEFORE INSERT ON v3_semantic_gate_attempt_heads
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM v3_semantic_gate_attempt_heads
    WHERE system_gate_evaluation_id = NEW.system_gate_evaluation_id
)
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate heads are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_heads_advance
BEFORE UPDATE OF current_sequence, current_attempt_id
ON v3_semantic_gate_attempt_heads
FOR EACH ROW
WHEN NEW.current_sequence <> OLD.current_sequence + 1
  OR NOT EXISTS (
      SELECT 1
      FROM v3_semantic_gate_attempts AS attempt
      WHERE attempt.attempt_id = NEW.current_attempt_id
        AND attempt.system_gate_evaluation_id =
            NEW.system_gate_evaluation_id
        AND attempt.session_id = NEW.session_id
        AND attempt.retrieval_snapshot_id = NEW.retrieval_snapshot_id
        AND attempt.sequence = NEW.current_sequence
        AND attempt.previous_attempt_id IS OLD.current_attempt_id
  )
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate head advance is invalid');
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_heads_immutable_delete
BEFORE DELETE ON v3_semantic_gate_attempt_heads
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate heads are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_attempts_parent_scope
BEFORE INSERT ON v3_semantic_gate_attempts
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_system_gate_evaluations AS evaluation
    JOIN v3_retrieval_snapshots AS snapshot
      ON snapshot.snapshot_id = evaluation.retrieval_snapshot_id
    WHERE evaluation.evaluation_id = NEW.system_gate_evaluation_id
      AND evaluation.session_id = NEW.session_id
      AND evaluation.retrieval_snapshot_id = NEW.retrieval_snapshot_id
      AND snapshot.session_id = NEW.session_id
)
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 semantic Gate attempt parent scope does not match'
    );
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_attempts_extend_head
BEFORE INSERT ON v3_semantic_gate_attempts
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_semantic_gate_attempt_heads AS head
    WHERE head.system_gate_evaluation_id =
        NEW.system_gate_evaluation_id
      AND head.session_id = NEW.session_id
      AND head.retrieval_snapshot_id = NEW.retrieval_snapshot_id
      AND head.current_sequence = NEW.sequence - 1
      AND head.current_attempt_id IS NEW.previous_attempt_id
)
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 semantic Gate attempt does not extend the current head'
    );
END;

CREATE TRIGGER IF NOT EXISTS
v3_semantic_gate_attempts_immutable_insert_conflict
BEFORE INSERT ON v3_semantic_gate_attempts
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM v3_semantic_gate_attempts
    WHERE attempt_id = NEW.attempt_id
       OR (
           system_gate_evaluation_id = NEW.system_gate_evaluation_id
           AND sequence = NEW.sequence
       )
)
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate attempts are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_attempts_immutable_update
BEFORE UPDATE ON v3_semantic_gate_attempts
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate attempts are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_semantic_gate_attempts_immutable_delete
BEFORE DELETE ON v3_semantic_gate_attempts
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 semantic Gate attempts are immutable');
END;
-- END COMPONENT semantic-gate

-- BEGIN COMPONENT semantic-gate-artifacts
CREATE TABLE IF NOT EXISTS
trace_backed_memory_v3_semantic_gate_artifacts_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.semantic-gate-artifact.v3')
) WITHOUT ROWID;

CREATE TRIGGER IF NOT EXISTS
v3_semantic_gate_artifacts_schema_requires_attempts
BEFORE INSERT ON trace_backed_memory_v3_semantic_gate_artifacts_schema
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM trace_backed_memory_v3_semantic_gate_schema
    WHERE singleton = 1
      AND schema_version = 1
      AND contract_version = 'tbm.semantic-gate-attempt.v3'
)
BEGIN
    SELECT RAISE(
        ABORT,
        'SQLite semantic Gate artifacts require semantic Gate v3'
    );
END;

INSERT OR IGNORE INTO
trace_backed_memory_v3_semantic_gate_artifacts_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.semantic-gate-artifact.v3');

CREATE TABLE IF NOT EXISTS v3_semantic_gate_artifacts (
    artifact_id TEXT PRIMARY KEY
        CHECK (
            length(artifact_id) = 80
            AND substr(artifact_id, 1, 16) = 'artifact_sha256_'
            AND substr(artifact_id, 17) NOT GLOB '*[^0-9a-f]*'
        ),
    content_sha256 TEXT NOT NULL UNIQUE
        CHECK (
            length(content_sha256) = 71
            AND substr(content_sha256, 1, 7) = 'sha256:'
            AND substr(content_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    size_bytes INTEGER NOT NULL CHECK (size_bytes BETWEEN 1 AND 128000),
    media_type TEXT NOT NULL
        CHECK (length(media_type) > 0 AND length(media_type) <= 512),
    classification TEXT NOT NULL
        CHECK (classification IN ('public', 'internal')),
    created_at TEXT NOT NULL CHECK (length(created_at) BETWEEN 20 AND 32),
    encryption_key_id TEXT CHECK (encryption_key_id IS NULL),
    redaction_policy_id TEXT
        CHECK (
            redaction_policy_id IS NULL
            OR (
                length(redaction_policy_id) > 0
                AND length(redaction_policy_id) <= 128
            )
        ),
    content BLOB NOT NULL,
    UNIQUE (artifact_id, content_sha256),
    CHECK (length(content) = size_bytes)
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_semantic_gate_artifact_bindings (
    attempt_id TEXT NOT NULL
        REFERENCES v3_semantic_gate_attempts(attempt_id),
    artifact_role TEXT NOT NULL
        CHECK (artifact_role IN ('prompt', 'response')),
    artifact_id TEXT NOT NULL,
    content_sha256 TEXT NOT NULL,
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        ),
    PRIMARY KEY (attempt_id, artifact_role),
    FOREIGN KEY (artifact_id, content_sha256)
        REFERENCES v3_semantic_gate_artifacts (
            artifact_id,
            content_sha256
        )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_semantic_gate_artifact_bindings_artifact
ON v3_semantic_gate_artifact_bindings(artifact_id);

CREATE TRIGGER IF NOT EXISTS
v3_semantic_gate_artifact_bindings_match_attempt
BEFORE INSERT ON v3_semantic_gate_artifact_bindings
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_semantic_gate_attempts AS attempt
    JOIN v3_semantic_gate_artifacts AS artifact
      ON artifact.artifact_id = NEW.artifact_id
     AND artifact.content_sha256 = NEW.content_sha256
    WHERE attempt.attempt_id = NEW.attempt_id
      AND (
          (
              NEW.artifact_role = 'prompt'
              AND artifact.size_bytes <= 128000
              AND artifact.media_type = 'text/plain; charset=utf-8'
              AND NEW.content_sha256 = json_extract(
                  attempt.descriptor,
                  '$.prompt_artifact_sha256'
              )
          )
          OR (
              NEW.artifact_role = 'response'
              AND attempt.status = 'succeeded'
              AND artifact.size_bytes <= 65536
              AND NEW.content_sha256 = json_extract(
                  attempt.descriptor,
                  '$.response_artifact_sha256'
              )
          )
      )
      AND json_valid(NEW.descriptor)
      AND (
          SELECT count(*) FROM json_each(NEW.descriptor)
      ) = 5
      AND (
          SELECT count(*)
          FROM json_each(NEW.descriptor, '$.artifact')
      ) = 8
      AND json_extract(
          NEW.descriptor,
          '$.contract_version'
      ) = 'tbm.semantic-gate-artifact.v3'
      AND json_extract(
          NEW.descriptor,
          '$.artifact_kind'
      ) = 'semantic_gate'
      AND json_extract(
          NEW.descriptor,
          '$.artifact_role'
      ) = NEW.artifact_role
      AND json_extract(
          NEW.descriptor,
          '$.attempt_id'
      ) = NEW.attempt_id
      AND json_extract(
          NEW.descriptor,
          '$.artifact.artifact_id'
      ) = artifact.artifact_id
      AND json_extract(
          NEW.descriptor,
          '$.artifact.content_sha256'
      ) = artifact.content_sha256
      AND json_extract(
          NEW.descriptor,
          '$.artifact.size_bytes'
      ) = artifact.size_bytes
      AND json_extract(
          NEW.descriptor,
          '$.artifact.media_type'
      ) = artifact.media_type
      AND json_extract(
          NEW.descriptor,
          '$.artifact.classification'
      ) = artifact.classification
      AND json_extract(
          NEW.descriptor,
          '$.artifact.created_at'
      ) = artifact.created_at
      AND json_extract(
          NEW.descriptor,
          '$.artifact.encryption_key_id'
      ) IS artifact.encryption_key_id
      AND json_extract(
          NEW.descriptor,
          '$.artifact.redaction_policy_id'
      ) IS artifact.redaction_policy_id
)
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 semantic Gate artifact binding does not match attempt'
    );
END;

CREATE TRIGGER IF NOT EXISTS
v3_semantic_gate_artifacts_verify_content
BEFORE INSERT ON v3_semantic_gate_artifacts
FOR EACH ROW
WHEN NEW.content_sha256 <> tbm_sha256(NEW.content)
  OR NEW.artifact_id <> (
      'artifact_sha256_' || substr(NEW.content_sha256, 8)
  )
BEGIN
    SELECT RAISE(
        ABORT,
        'v3 semantic Gate artifact bytes do not match identity'
    );
END;

