-- BEGIN COMPONENT replay
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_replay_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1)
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_replay_schema (
    singleton,
    schema_version
) VALUES (1, 1);

CREATE TABLE IF NOT EXISTS v3_replay_artifacts (
    artifact_id TEXT PRIMARY KEY
        CHECK (
            length(artifact_id) = 80
            AND substr(artifact_id, 1, 16) = 'artifact_sha256_'
            AND substr(artifact_id, 17) NOT GLOB '*[^0-9a-f]*'
        ),
    content_sha256 TEXT NOT NULL UNIQUE
        CHECK (
            length(content_sha256) = 71
            AND substr(content_sha256, 1, 7) = 'sha256:'
            AND substr(content_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    size_bytes INTEGER NOT NULL
        CHECK (size_bytes >= 0 AND size_bytes <= 67108864),
    media_type TEXT NOT NULL
        CHECK (length(media_type) > 0 AND length(media_type) <= 512),
    classification TEXT NOT NULL
        CHECK (
            classification IN (
                'public',
                'internal'
            )
        ),
    created_at TEXT NOT NULL
        CHECK (length(created_at) > 0 AND length(created_at) <= 64),
    encryption_key_id TEXT
        CHECK (
            encryption_key_id IS NULL
            OR (
                length(encryption_key_id) > 0
                AND length(encryption_key_id) <= 128
            )
        ),
    redaction_policy_id TEXT
        CHECK (
            redaction_policy_id IS NULL
            OR (
                length(redaction_policy_id) > 0
                AND length(redaction_policy_id) <= 128
            )
        ),
    content BLOB NOT NULL
        CHECK (
            length(content) = size_bytes
            AND length(content) <= 67108864
        ),
    CHECK (encryption_key_id IS NULL)
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_replay_injections (
    artifact_id TEXT PRIMARY KEY
        REFERENCES v3_replay_artifacts(artifact_id),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    decision_id TEXT NOT NULL
        CHECK (length(decision_id) > 0 AND length(decision_id) <= 128),
    usage_decision_id TEXT NOT NULL
        CHECK (
            length(usage_decision_id) > 0
            AND length(usage_decision_id) <= 128
        ),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_replay_injections_decision
ON v3_replay_injections(session_id, decision_id, usage_decision_id);

CREATE TABLE IF NOT EXISTS v3_replay_manifests (
    manifest_sha256 TEXT PRIMARY KEY
        CHECK (
            length(manifest_sha256) = 71
            AND substr(manifest_sha256, 1, 7) = 'sha256:'
            AND substr(manifest_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    decision_id TEXT NOT NULL
        CHECK (length(decision_id) > 0 AND length(decision_id) <= 128),
    usage_decision_id TEXT NOT NULL
        CHECK (
            length(usage_decision_id) > 0
            AND length(usage_decision_id) <= 128
        ),
    injection_artifact_id TEXT
        REFERENCES v3_replay_injections(artifact_id),
    completeness TEXT NOT NULL
        CHECK (completeness IN ('complete', 'legacy_partial')),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        )
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_replay_manifests_decision
ON v3_replay_manifests(session_id, decision_id, usage_decision_id);

CREATE TRIGGER IF NOT EXISTS v3_replay_artifacts_immutable_update
BEFORE UPDATE ON v3_replay_artifacts
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay artifacts are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_replay_artifacts_immutable_delete
BEFORE DELETE ON v3_replay_artifacts
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay artifacts are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_replay_injections_immutable_update
BEFORE UPDATE ON v3_replay_injections
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay injections are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_replay_injections_immutable_delete
BEFORE DELETE ON v3_replay_injections
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay injections are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_replay_manifests_immutable_update
BEFORE UPDATE ON v3_replay_manifests
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay manifests are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_replay_manifests_immutable_delete
BEFORE DELETE ON v3_replay_manifests
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 replay manifests are immutable');
END;
-- END COMPONENT replay

-- BEGIN COMPONENT outcome
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_outcome_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.run-outcome.v3')
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_outcome_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.run-outcome.v3');

CREATE TABLE IF NOT EXISTS v3_run_outcomes (
    run_outcome_id TEXT PRIMARY KEY CHECK (
        length(run_outcome_id) = 83
        AND substr(run_outcome_id, 1, 19) = 'run_outcome_sha256_'
        AND substr(run_outcome_id, 20) NOT GLOB '*[^0-9a-f]*'
    ),
    session_id TEXT NOT NULL UNIQUE
        CHECK (length(session_id) BETWEEN 1 AND 128),
    trace_id TEXT NOT NULL
        CHECK (length(trace_id) BETWEEN 1 AND 128),
    run_id TEXT NOT NULL
        CHECK (length(run_id) BETWEEN 1 AND 128),
    usage_decision_id TEXT NOT NULL
        CHECK (length(usage_decision_id) BETWEEN 1 AND 128),
    result TEXT NOT NULL CHECK (result IN ('pass', 'fail', 'error')),
    evaluator_id TEXT NOT NULL
        CHECK (length(evaluator_id) BETWEEN 1 AND 128),
    evaluator_version TEXT NOT NULL
        CHECK (length(evaluator_version) BETWEEN 1 AND 128),
    output_sha256 TEXT CHECK (
        output_sha256 IS NULL
        OR (
            length(output_sha256) = 71
            AND substr(output_sha256, 1, 7) = 'sha256:'
            AND substr(output_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        )
    ),
    tool_outputs_sha256 TEXT CHECK (
        tool_outputs_sha256 IS NULL
        OR (
            length(tool_outputs_sha256) = 71
            AND substr(tool_outputs_sha256, 1, 7) = 'sha256:'
            AND substr(tool_outputs_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        )
    ),
    evidence_artifact_sha256s_json TEXT NOT NULL CHECK (
        length(CAST(evidence_artifact_sha256s_json AS BLOB))
            BETWEEN 1 AND 8192
        AND json_valid(evidence_artifact_sha256s_json)
        AND json_type(evidence_artifact_sha256s_json) = 'array'
        AND json_array_length(evidence_artifact_sha256s_json)
            BETWEEN 1 AND 64
    ),
    latency_ms INTEGER CHECK (
        latency_ms IS NULL
        OR latency_ms BETWEEN 0 AND 2147483647
    ),
    cost_usd_json TEXT NOT NULL CHECK (
        cost_usd_json = 'null'
        OR (
            json_valid(cost_usd_json)
            AND json_type(cost_usd_json) IN ('integer', 'real')
            AND CAST(cost_usd_json AS REAL) >= 0
        )
    ),
    error_code TEXT CHECK (
        error_code IS NULL
        OR length(error_code) BETWEEN 1 AND 1024
    ),
    measured_at TEXT NOT NULL
        CHECK (length(measured_at) BETWEEN 20 AND 32),
    descriptor TEXT NOT NULL CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 1 AND 1048576
        AND json_valid(descriptor)
    ),
    CHECK (output_sha256 IS NOT NULL OR tool_outputs_sha256 IS NOT NULL),
    CHECK (
        (result = 'error' AND error_code IS NOT NULL)
        OR (result <> 'error' AND error_code IS NULL)
    ),
    FOREIGN KEY (session_id)
        REFERENCES gate_session_heads (session_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) WITHOUT ROWID;

CREATE TRIGGER IF NOT EXISTS v3_run_outcomes_validate_insert
BEFORE INSERT ON v3_run_outcomes
FOR EACH ROW
WHEN
    EXISTS (
        SELECT 1
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS artifact
        WHERE artifact.type <> 'text'
           OR length(artifact.value) <> 71
           OR substr(artifact.value, 1, 7) <> 'sha256:'
           OR substr(artifact.value, 8) GLOB '*[^0-9a-f]*'
    )
    OR (
        SELECT COUNT(*)
        FROM json_each(NEW.evidence_artifact_sha256s_json)
    ) <> (
        SELECT COUNT(DISTINCT artifact.value)
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS artifact
    )
    OR EXISTS (
        SELECT 1
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS current
        JOIN json_each(NEW.evidence_artifact_sha256s_json) AS previous
          ON CAST(previous.key AS INTEGER)
             = CAST(current.key AS INTEGER) - 1
        WHERE current.value <= previous.value
    )
    OR NEW.descriptor <> (
        '{"contract_version":"tbm.run-outcome.v3"'
        || ',"cost_usd":' || NEW.cost_usd_json
        || ',"error_code":' || json_quote(NEW.error_code)
        || ',"evaluator_id":' || json_quote(NEW.evaluator_id)
        || ',"evaluator_version":' || json_quote(NEW.evaluator_version)
        || ',"evidence_artifact_sha256s":'
        || NEW.evidence_artifact_sha256s_json
        || ',"latency_ms":'
        || COALESCE(CAST(NEW.latency_ms AS TEXT), 'null')
        || ',"measured_at":' || json_quote(NEW.measured_at)
        || ',"output_sha256":' || json_quote(NEW.output_sha256)
        || ',"result":' || json_quote(NEW.result)
        || ',"run_id":' || json_quote(NEW.run_id)
        || ',"run_outcome_id":' || json_quote(NEW.run_outcome_id)
        || ',"session_id":' || json_quote(NEW.session_id)
        || ',"tool_outputs_sha256":'
        || json_quote(NEW.tool_outputs_sha256)
        || ',"trace_id":' || json_quote(NEW.trace_id)
        || ',"usage_decision_id":' || json_quote(NEW.usage_decision_id)
        || '}'
    )
    OR NOT EXISTS (
        SELECT 1
        FROM gate_session_heads AS head
        JOIN gate_session_revisions AS revision
          ON revision.session_id = head.session_id
         AND revision.version = head.current_version
        WHERE head.session_id = NEW.session_id
          AND head.trace_id = NEW.trace_id
          AND head.run_id = NEW.run_id
          AND revision.status = 'completed'
          AND revision.updated_at = NEW.measured_at
          AND json_extract(revision.payload, '$.usage_decision_id')
              = NEW.usage_decision_id
          AND json_extract(revision.payload, '$.run_outcome_id')
              = NEW.run_outcome_id
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid RunOutcome record');
END;

CREATE TRIGGER IF NOT EXISTS v3_run_outcomes_immutable_update
BEFORE UPDATE ON v3_run_outcomes
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'RunOutcome is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_run_outcomes_immutable_delete
BEFORE DELETE ON v3_run_outcomes
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'RunOutcome is immutable');
END;
-- END COMPONENT outcome

-- BEGIN COMPONENT outcome-attribution
CREATE TABLE trace_backed_memory_v3_outcome_attribution_schema (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL CHECK (
        contract_version = 'tbm.outcome-attribution.v3'
    )
);

INSERT INTO trace_backed_memory_v3_outcome_attribution_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.outcome-attribution.v3');

CREATE TABLE v3_outcome_attributions (
    attribution_id TEXT PRIMARY KEY CHECK (
        length(attribution_id) = 91
        AND substr(attribution_id, 1, 27)
            = 'outcome_attribution_sha256_'
        AND substr(attribution_id, 28) NOT GLOB '*[^0-9a-f]*'
    ),
    run_outcome_id TEXT NOT NULL CHECK (
        length(run_outcome_id) = 83
        AND substr(run_outcome_id, 1, 19) = 'run_outcome_sha256_'
        AND substr(run_outcome_id, 20) NOT GLOB '*[^0-9a-f]*'
    ),
    usage_decision_id TEXT NOT NULL CHECK (
        length(usage_decision_id) BETWEEN 1 AND 128
    ),
    memory_revision_ids_json TEXT NOT NULL CHECK (
        length(CAST(memory_revision_ids_json AS BLOB)) BETWEEN 1 AND 8192
        AND json_valid(memory_revision_ids_json)
        AND json_type(memory_revision_ids_json) = 'array'
        AND json_array_length(memory_revision_ids_json) BETWEEN 1 AND 50
    ),
    claim_strength TEXT NOT NULL CHECK (
        claim_strength IN ('association', 'causal')
    ),
    effect TEXT NOT NULL CHECK (
        effect IN ('helped', 'harmed', 'neutral', 'unknown')
    ),
    method TEXT NOT NULL CHECK (
        method IN (
            'runtime_observation',
            'controlled_experiment',
            'manual_review',
            'external_evaluation'
        )
    ),
    evaluator_id TEXT NOT NULL CHECK (
        length(evaluator_id) BETWEEN 1 AND 128
    ),
    evaluator_version TEXT NOT NULL CHECK (
        length(evaluator_version) BETWEEN 1 AND 128
    ),
    verifier_id TEXT CHECK (
        verifier_id IS NULL OR length(verifier_id) BETWEEN 1 AND 128
    ),
    evidence_artifact_sha256s_json TEXT NOT NULL CHECK (
        length(CAST(evidence_artifact_sha256s_json AS BLOB))
            BETWEEN 1 AND 8192
        AND json_valid(evidence_artifact_sha256s_json)
        AND json_type(evidence_artifact_sha256s_json) = 'array'
        AND json_array_length(evidence_artifact_sha256s_json)
            BETWEEN 1 AND 64
    ),
    confidence_json TEXT NOT NULL CHECK (
        length(confidence_json) BETWEEN 1 AND 128
        AND json_valid(confidence_json)
        AND json_type(confidence_json) = 'real'
        AND CAST(confidence_json AS REAL) BETWEEN 0.0 AND 1.0
    ),
    reason TEXT NOT NULL CHECK (
        length(reason) BETWEEN 1 AND 1024
    ),
    recorded_at TEXT NOT NULL CHECK (
        length(recorded_at) BETWEEN 20 AND 32
    ),
    descriptor TEXT NOT NULL CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 1 AND 1048576
        AND json_valid(descriptor)
    ),
    FOREIGN KEY (run_outcome_id)
        REFERENCES v3_run_outcomes (run_outcome_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) WITHOUT ROWID;

CREATE INDEX v3_outcome_attributions_by_outcome
ON v3_outcome_attributions (
    run_outcome_id,
    recorded_at,
    attribution_id
);

CREATE TRIGGER v3_outcome_attribution_schema_immutable_insert
BEFORE INSERT ON trace_backed_memory_v3_outcome_attribution_schema
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM trace_backed_memory_v3_outcome_attribution_schema
)
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution schema metadata is immutable');
END;

CREATE TRIGGER v3_outcome_attribution_schema_immutable_update
BEFORE UPDATE ON trace_backed_memory_v3_outcome_attribution_schema
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution schema metadata is immutable');
END;

CREATE TRIGGER v3_outcome_attribution_schema_immutable_delete
BEFORE DELETE ON trace_backed_memory_v3_outcome_attribution_schema
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution schema metadata is immutable');
END;

CREATE TRIGGER v3_outcome_attributions_immutable_insert
BEFORE INSERT ON v3_outcome_attributions
FOR EACH ROW
WHEN EXISTS (
    SELECT 1
    FROM v3_outcome_attributions
    WHERE attribution_id = NEW.attribution_id
)
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution is immutable');
END;

CREATE TRIGGER v3_outcome_attributions_validate_insert
BEFORE INSERT ON v3_outcome_attributions
FOR EACH ROW
WHEN
    tbm_validate_outcome_attribution(NEW.descriptor) <> 1
    OR tbm_validate_outcome_attribution_row(
        NEW.attribution_id,
        NEW.run_outcome_id,
        NEW.usage_decision_id,
        NEW.memory_revision_ids_json,
        NEW.claim_strength,
        NEW.effect,
        NEW.method,
        NEW.evaluator_id,
        NEW.evaluator_version,
        NEW.verifier_id,
        NEW.evidence_artifact_sha256s_json,
        NEW.confidence_json,
        NEW.reason,
        NEW.recorded_at,
        NEW.descriptor
    ) <> 1
    OR EXISTS (
        SELECT 1
        FROM json_each(NEW.memory_revision_ids_json) AS revision
        WHERE revision.type <> 'text'
           OR length(revision.value) <> 87
           OR substr(revision.value, 1, 23)
              <> 'memory_revision_sha256_'
           OR substr(revision.value, 24) GLOB '*[^0-9a-f]*'
    )
    OR (
        SELECT COUNT(*)
        FROM json_each(NEW.memory_revision_ids_json)
    ) <> (
        SELECT COUNT(DISTINCT revision.value)
        FROM json_each(NEW.memory_revision_ids_json) AS revision
    )
    OR EXISTS (
        SELECT 1
        FROM json_each(NEW.memory_revision_ids_json) AS current
        JOIN json_each(NEW.memory_revision_ids_json) AS previous
          ON CAST(previous.key AS INTEGER)
             = CAST(current.key AS INTEGER) - 1
        WHERE current.value <= previous.value
    )
    OR EXISTS (
        SELECT 1
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS artifact
        WHERE artifact.type <> 'text'
           OR length(artifact.value) <> 71
           OR substr(artifact.value, 1, 7) <> 'sha256:'
           OR substr(artifact.value, 8) GLOB '*[^0-9a-f]*'
    )
    OR (
        SELECT COUNT(*)
        FROM json_each(NEW.evidence_artifact_sha256s_json)
    ) <> (
        SELECT COUNT(DISTINCT artifact.value)
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS artifact
    )
    OR EXISTS (
        SELECT 1
        FROM json_each(NEW.evidence_artifact_sha256s_json) AS current
        JOIN json_each(NEW.evidence_artifact_sha256s_json) AS previous
          ON CAST(previous.key AS INTEGER)
             = CAST(current.key AS INTEGER) - 1
        WHERE current.value <= previous.value
    )
    OR (
        NEW.claim_strength = 'association'
        AND (
            NEW.method <> 'runtime_observation'
            OR NEW.verifier_id IS NOT NULL
        )
    )
    OR (
        NEW.claim_strength = 'causal'
        AND (
            NEW.method NOT IN (
                'controlled_experiment',
                'manual_review',
                'external_evaluation'
            )
            OR NEW.verifier_id IS NULL
            OR NEW.verifier_id = NEW.evaluator_id
            OR NEW.effect = 'unknown'
        )
    )
    OR NEW.descriptor <> (
        '{"attribution_id":' || json_quote(NEW.attribution_id)
        || ',"claim_strength":' || json_quote(NEW.claim_strength)
        || ',"confidence":' || NEW.confidence_json
        || ',"contract_version":"tbm.outcome-attribution.v3"'
        || ',"effect":' || json_quote(NEW.effect)
        || ',"evaluator_id":' || json_quote(NEW.evaluator_id)
        || ',"evaluator_version":' || json_quote(NEW.evaluator_version)
        || ',"evidence_artifact_sha256s":'
        || NEW.evidence_artifact_sha256s_json
        || ',"memory_revision_ids":' || NEW.memory_revision_ids_json
        || ',"method":' || json_quote(NEW.method)
        || ',"reason":' || json_quote(NEW.reason)
        || ',"recorded_at":' || json_quote(NEW.recorded_at)
        || ',"run_outcome_id":' || json_quote(NEW.run_outcome_id)
        || ',"usage_decision_id":' || json_quote(NEW.usage_decision_id)
        || ',"verifier_id":' || json_quote(NEW.verifier_id)
        || '}'
    )
    OR NOT EXISTS (
        SELECT 1
        FROM v3_run_outcomes AS outcome
        JOIN gate_session_heads AS head
          ON head.session_id = outcome.session_id
        JOIN gate_session_revisions AS revision
          ON revision.session_id = head.session_id
         AND revision.version = head.current_version
        WHERE outcome.run_outcome_id = NEW.run_outcome_id
          AND tbm_validate_run_outcome_row(
              outcome.run_outcome_id,
              outcome.session_id,
              outcome.trace_id,
              outcome.run_id,
              outcome.usage_decision_id,
              outcome.result,
              outcome.evaluator_id,
              outcome.evaluator_version,
              outcome.output_sha256,
              outcome.tool_outputs_sha256,
              outcome.evidence_artifact_sha256s_json,
              outcome.latency_ms,
              outcome.cost_usd_json,
              outcome.error_code,
              outcome.measured_at,
              outcome.descriptor
          ) = 1
          AND outcome.usage_decision_id = NEW.usage_decision_id
          AND revision.status = 'completed'
          AND json_extract(revision.payload, '$.run_outcome_id')
              = outcome.run_outcome_id
          AND json_extract(revision.payload, '$.usage_decision_id')
              = outcome.usage_decision_id
          AND tbm_outcome_attribution_time_not_before(
              NEW.recorded_at,
              outcome.measured_at
          ) = 1
          AND NOT EXISTS (
              SELECT 1
              FROM json_each(NEW.memory_revision_ids_json) AS claimed
              WHERE NOT EXISTS (
                  SELECT 1
                  FROM json_each(
                      revision.payload,
                      '$.final_memory_revision_ids'
                  ) AS finalized
                  WHERE finalized.value = claimed.value
              )
          )
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid OutcomeAttribution record');
END;

CREATE TRIGGER v3_outcome_attributions_immutable_update
BEFORE UPDATE ON v3_outcome_attributions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution is immutable');
END;

CREATE TRIGGER v3_outcome_attributions_immutable_delete
BEFORE DELETE ON v3_outcome_attributions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'OutcomeAttribution is immutable');
END;
-- END COMPONENT outcome-attribution

-- BEGIN COMPONENT completion-outbox
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_completion_outbox_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.completion-outbox.v3')
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_completion_outbox_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.completion-outbox.v3');

CREATE TABLE IF NOT EXISTS v3_completion_outbox_events (
    event_id TEXT PRIMARY KEY CHECK (
        length(event_id) = 95
        AND substr(event_id, 1, 31)
            = 'completion_outbox_event_sha256_'
        AND substr(event_id, 32) NOT GLOB '*[^0-9a-f]*'
    ),
    event_type TEXT NOT NULL CHECK (event_type = 'execution_completed'),
    tenant_id TEXT NOT NULL CHECK (length(tenant_id) BETWEEN 1 AND 128),
    repository_id TEXT NOT NULL
        CHECK (length(repository_id) BETWEEN 1 AND 128),
    session_id TEXT NOT NULL CHECK (length(session_id) BETWEEN 1 AND 128),
    trace_id TEXT NOT NULL CHECK (length(trace_id) BETWEEN 1 AND 128),
    run_id TEXT NOT NULL CHECK (length(run_id) BETWEEN 1 AND 128),
    usage_decision_id TEXT NOT NULL
        CHECK (length(usage_decision_id) BETWEEN 1 AND 128),
    run_outcome_id TEXT NOT NULL UNIQUE CHECK (
        length(run_outcome_id) = 83
        AND substr(run_outcome_id, 1, 19) = 'run_outcome_sha256_'
        AND substr(run_outcome_id, 20) NOT GLOB '*[^0-9a-f]*'
    ),
    outcome_descriptor_sha256 TEXT NOT NULL CHECK (
        length(outcome_descriptor_sha256) = 71
        AND substr(outcome_descriptor_sha256, 1, 7) = 'sha256:'
        AND substr(outcome_descriptor_sha256, 8)
            NOT GLOB '*[^0-9a-f]*'
    ),
    occurred_at TEXT NOT NULL
        CHECK (length(occurred_at) BETWEEN 20 AND 32),
    occurred_at_us INTEGER NOT NULL,
    descriptor TEXT NOT NULL CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 1 AND 1048576
        AND json_valid(descriptor)
    ),
    FOREIGN KEY (run_outcome_id)
        REFERENCES v3_run_outcomes (run_outcome_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    FOREIGN KEY (session_id)
        REFERENCES gate_session_heads (session_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_completion_outbox_delivery_revisions (
    event_id TEXT NOT NULL,
    version INTEGER NOT NULL CHECK (version >= 1),
    delivery_revision_id TEXT NOT NULL UNIQUE CHECK (
        length(delivery_revision_id) = 98
        AND substr(delivery_revision_id, 1, 34)
            = 'completion_outbox_delivery_sha256_'
        AND substr(delivery_revision_id, 35) NOT GLOB '*[^0-9a-f]*'
    ),
    status TEXT NOT NULL CHECK (
        status IN (
            'pending',
            'leased',
            'retry_wait',
            'delivered',
            'dead_letter'
        )
    ),
    attempt_count INTEGER NOT NULL
        CHECK (attempt_count BETWEEN 0 AND 1000),
    updated_at TEXT NOT NULL
        CHECK (length(updated_at) BETWEEN 20 AND 32),
    updated_at_us INTEGER NOT NULL,
    available_at TEXT
        CHECK (
            available_at IS NULL
            OR length(available_at) BETWEEN 20 AND 32
        ),
    available_at_us INTEGER,
    worker_id TEXT
        CHECK (
            worker_id IS NULL
            OR length(worker_id) BETWEEN 1 AND 128
        ),
    lease_expires_at TEXT
        CHECK (
            lease_expires_at IS NULL
            OR length(lease_expires_at) BETWEEN 20 AND 32
        ),
    lease_expires_at_us INTEGER,
    delivered_at TEXT
        CHECK (
            delivered_at IS NULL
            OR length(delivered_at) BETWEEN 20 AND 32
        ),
    delivered_at_us INTEGER,
    last_error_code TEXT
        CHECK (
            last_error_code IS NULL
            OR length(last_error_code) BETWEEN 1 AND 256
        ),
    response_sha256 TEXT CHECK (
        response_sha256 IS NULL
        OR (
            length(response_sha256) = 71
            AND substr(response_sha256, 1, 7) = 'sha256:'
            AND substr(response_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        )
    ),
    descriptor TEXT NOT NULL CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 1 AND 1048576
        AND json_valid(descriptor)
    ),
    PRIMARY KEY (event_id, version),
    FOREIGN KEY (event_id)
        REFERENCES v3_completion_outbox_events (event_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_completion_outbox_delivery_heads (
    event_id TEXT PRIMARY KEY,
    current_version INTEGER NOT NULL CHECK (current_version >= 1),
    FOREIGN KEY (event_id, current_version)
        REFERENCES v3_completion_outbox_delivery_revisions (
            event_id,
            version
        )
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
        DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_completion_outbox_due
ON v3_completion_outbox_delivery_revisions (
    status,
    available_at_us,
    lease_expires_at_us,
    event_id,
    version
)
WHERE status IN ('pending', 'retry_wait', 'leased');

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_events_validate_insert
BEFORE INSERT ON v3_completion_outbox_events
FOR EACH ROW
WHEN
    tbm_v3_completion_outbox_mutation_allowed() <> 1
    OR tbm_v3_completion_outbox_event_is_canonical(
        NEW.event_id,
        NEW.event_type,
        NEW.tenant_id,
        NEW.repository_id,
        NEW.session_id,
        NEW.trace_id,
        NEW.run_id,
        NEW.usage_decision_id,
        NEW.run_outcome_id,
        NEW.outcome_descriptor_sha256,
        NEW.occurred_at,
        NEW.occurred_at_us,
        NEW.descriptor
    ) <> 1
    OR NOT EXISTS (
        SELECT 1
        FROM v3_run_outcomes AS outcome
        JOIN gate_session_heads AS head
          ON head.session_id = outcome.session_id
        JOIN gate_session_revisions AS revision
          ON revision.session_id = head.session_id
         AND revision.version = head.current_version
        WHERE outcome.run_outcome_id = NEW.run_outcome_id
          AND outcome.session_id = NEW.session_id
          AND outcome.trace_id = NEW.trace_id
          AND outcome.run_id = NEW.run_id
          AND outcome.usage_decision_id = NEW.usage_decision_id
          AND outcome.measured_at = NEW.occurred_at
          AND head.tenant_id = NEW.tenant_id
          AND head.repository_id = NEW.repository_id
          AND revision.status = 'completed'
          AND json_extract(revision.payload, '$.run_outcome_id')
              = NEW.run_outcome_id
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid completion outbox event');
END;

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_events_immutable_update
BEFORE UPDATE ON v3_completion_outbox_events
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'completion outbox event is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_events_immutable_delete
BEFORE DELETE ON v3_completion_outbox_events
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'completion outbox event is immutable');
END;

CREATE TRIGGER IF NOT EXISTS
v3_completion_outbox_delivery_revisions_validate_insert
BEFORE INSERT ON v3_completion_outbox_delivery_revisions
FOR EACH ROW
WHEN
    tbm_v3_completion_outbox_mutation_allowed() <> 1
    OR tbm_v3_completion_outbox_delivery_is_canonical(
        NEW.event_id,
        NEW.version,
        NEW.delivery_revision_id,
        NEW.status,
        NEW.attempt_count,
        NEW.updated_at,
        NEW.updated_at_us,
        NEW.available_at,
        NEW.available_at_us,
        NEW.worker_id,
        NEW.lease_expires_at,
        NEW.lease_expires_at_us,
        NEW.delivered_at,
        NEW.delivered_at_us,
        NEW.last_error_code,
        NEW.response_sha256,
        NEW.descriptor
    ) <> 1
    OR (
        NEW.version = 1
        AND (
            NEW.status <> 'pending'
            OR EXISTS (
                SELECT 1
                FROM v3_completion_outbox_delivery_revisions AS existing
                WHERE existing.event_id = NEW.event_id
            )
        )
    )
    OR (
        NEW.version > 1
        AND (
            NOT EXISTS (
                SELECT 1
                FROM v3_completion_outbox_delivery_heads AS head
                WHERE head.event_id = NEW.event_id
                  AND head.current_version = NEW.version - 1
            )
            OR tbm_v3_completion_outbox_transition_is_valid(
                (
                    SELECT previous.descriptor
                    FROM v3_completion_outbox_delivery_revisions AS previous
                    WHERE previous.event_id = NEW.event_id
                      AND previous.version = NEW.version - 1
                ),
                NEW.descriptor
            ) <> 1
        )
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid completion outbox delivery revision');
END;

CREATE TRIGGER IF NOT EXISTS
v3_completion_outbox_delivery_revisions_immutable_update
BEFORE UPDATE ON v3_completion_outbox_delivery_revisions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'completion outbox delivery revision is immutable');
END;

CREATE TRIGGER IF NOT EXISTS
v3_completion_outbox_delivery_revisions_immutable_delete
BEFORE DELETE ON v3_completion_outbox_delivery_revisions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'completion outbox delivery revision is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_delivery_heads_validate_insert
BEFORE INSERT ON v3_completion_outbox_delivery_heads
FOR EACH ROW
WHEN
    tbm_v3_completion_outbox_mutation_allowed() <> 1
    OR NEW.current_version <> 1
    OR NOT EXISTS (
        SELECT 1
        FROM v3_completion_outbox_delivery_revisions AS revision
        WHERE revision.event_id = NEW.event_id
          AND revision.version = 1
          AND revision.status = 'pending'
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid completion outbox delivery head');
END;

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_delivery_heads_advance
BEFORE UPDATE ON v3_completion_outbox_delivery_heads
FOR EACH ROW
WHEN
    tbm_v3_completion_outbox_mutation_allowed() <> 1
    OR NEW.event_id <> OLD.event_id
    OR NEW.current_version <> OLD.current_version + 1
    OR NOT EXISTS (
        SELECT 1
        FROM v3_completion_outbox_delivery_revisions AS revision
        WHERE revision.event_id = NEW.event_id
          AND revision.version = NEW.current_version
    )
BEGIN
    SELECT RAISE(ABORT, 'invalid completion outbox head advance');
END;

CREATE TRIGGER IF NOT EXISTS v3_completion_outbox_delivery_heads_no_delete
BEFORE DELETE ON v3_completion_outbox_delivery_heads
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'completion outbox delivery head is immutable');
END;
-- END COMPONENT completion-outbox

-- BEGIN COMPONENT audit
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_audit_schema (
    singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL
        CHECK (contract_version = 'tbm.audit-event.v3')
) WITHOUT ROWID;

INSERT OR IGNORE INTO trace_backed_memory_v3_audit_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.audit-event.v3');

CREATE TABLE IF NOT EXISTS v3_audit_stream_heads (
    stream_id TEXT PRIMARY KEY
        CHECK (length(stream_id) > 0 AND length(stream_id) <= 128),
    tenant_id TEXT NOT NULL
        CHECK (length(tenant_id) > 0 AND length(tenant_id) <= 128),
    repository_id TEXT NOT NULL
        CHECK (length(repository_id) > 0 AND length(repository_id) <= 128),
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    trace_id TEXT NOT NULL
        CHECK (length(trace_id) > 0 AND length(trace_id) <= 128),
    run_id TEXT NOT NULL
        CHECK (length(run_id) > 0 AND length(run_id) <= 128),
    current_sequence INTEGER NOT NULL
        CHECK (
            current_sequence >= 0
            AND current_sequence <= 2147483647
        ),
    current_event_id TEXT
        CHECK (
            current_event_id IS NULL
            OR (
                length(current_event_id) = 83
                AND substr(current_event_id, 1, 19) =
                    'audit_event_sha256_'
                AND substr(current_event_id, 20)
                    NOT GLOB '*[^0-9a-f]*'
            )
        ),
    CHECK (
        (current_sequence = 0 AND current_event_id IS NULL)
        OR (current_sequence > 0 AND current_event_id IS NOT NULL)
    )
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS v3_audit_events (
    event_id TEXT PRIMARY KEY
        CHECK (
            length(event_id) = 83
            AND substr(event_id, 1, 19) = 'audit_event_sha256_'
            AND substr(event_id, 20) NOT GLOB '*[^0-9a-f]*'
        ),
    stream_id TEXT NOT NULL
        REFERENCES v3_audit_stream_heads(stream_id),
    sequence INTEGER NOT NULL
        CHECK (sequence >= 1 AND sequence <= 2147483647),
    previous_event_id TEXT,
    tenant_id TEXT NOT NULL,
    repository_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    trace_id TEXT NOT NULL,
    run_id TEXT NOT NULL,
    actor_type TEXT NOT NULL
        CHECK (actor_type IN ('principal', 'service', 'worker')),
    actor_id TEXT NOT NULL
        CHECK (length(actor_id) > 0 AND length(actor_id) <= 128),
    event_type TEXT NOT NULL
        CHECK (
            event_type IN (
                'session_created',
                'session_transitioned',
                'authorization_evaluated',
                'retrieval_recorded',
                'system_gate_evaluated',
                'semantic_gate_attempted',
                'decision_finalized',
                'injection_created',
                'execution_completed',
                'outcome_attributed',
                'recovery_succeeded',
                'recovery_failed',
                'session_canceled',
                'session_expired',
                'session_abandoned'
            )
        ),
    recovery_action_id TEXT
        CHECK (
            recovery_action_id IS NULL
            OR (
                length(recovery_action_id) = 87
                AND substr(recovery_action_id, 1, 23) =
                    'recovery_action_sha256_'
                AND substr(recovery_action_id, 24)
                    NOT GLOB '*[^0-9a-f]*'
            )
        ),
    reason_code TEXT NOT NULL
        CHECK (length(reason_code) > 0 AND length(reason_code) <= 256),
    payload_sha256 TEXT NOT NULL
        CHECK (
            length(payload_sha256) = 71
            AND substr(payload_sha256, 1, 7) = 'sha256:'
            AND substr(payload_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    occurred_at TEXT NOT NULL
        CHECK (length(occurred_at) > 0 AND length(occurred_at) <= 64),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
    ),
    UNIQUE (stream_id, sequence),
    UNIQUE (stream_id, event_id),
    UNIQUE (recovery_action_id),
    UNIQUE (recovery_action_id, event_id),
    CHECK (
        (
            event_type IN ('recovery_succeeded', 'recovery_failed')
            AND recovery_action_id IS NOT NULL
        )
        OR (
            event_type NOT IN ('recovery_succeeded', 'recovery_failed')
            AND recovery_action_id IS NULL
        )
    ),
    FOREIGN KEY (stream_id, previous_event_id)
        REFERENCES v3_audit_events(stream_id, event_id)
        DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (recovery_action_id)
        REFERENCES v3_recovery_actions(recovery_action_id)
        DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_audit_events_session
ON v3_audit_events(session_id, sequence);

CREATE INDEX IF NOT EXISTS v3_audit_events_type
ON v3_audit_events(event_type, occurred_at);

CREATE TABLE IF NOT EXISTS v3_recovery_actions (
    recovery_action_id TEXT PRIMARY KEY
        CHECK (
            length(recovery_action_id) = 87
            AND substr(recovery_action_id, 1, 23) =
                'recovery_action_sha256_'
            AND substr(recovery_action_id, 24)
                NOT GLOB '*[^0-9a-f]*'
        ),
    event_id TEXT NOT NULL UNIQUE,
    session_id TEXT NOT NULL
        CHECK (length(session_id) > 0 AND length(session_id) <= 128),
    request_sha256 TEXT NOT NULL
        CHECK (
            length(request_sha256) = 71
            AND substr(request_sha256, 1, 7) = 'sha256:'
            AND substr(request_sha256, 8) NOT GLOB '*[^0-9a-f]*'
        ),
    descriptor TEXT NOT NULL
        CHECK (
            length(CAST(descriptor AS BLOB)) > 0
            AND length(CAST(descriptor AS BLOB)) <= 1048576
        ),
    UNIQUE (session_id, request_sha256),
    FOREIGN KEY (recovery_action_id, event_id)
        REFERENCES v3_audit_events(recovery_action_id, event_id)
        DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS v3_recovery_actions_session
ON v3_recovery_actions(session_id, recovery_action_id);

CREATE TRIGGER IF NOT EXISTS v3_audit_stream_heads_identity_immutable
BEFORE UPDATE ON v3_audit_stream_heads
FOR EACH ROW
WHEN
    NEW.stream_id <> OLD.stream_id
    OR NEW.tenant_id <> OLD.tenant_id
    OR NEW.repository_id <> OLD.repository_id
    OR NEW.session_id <> OLD.session_id
    OR NEW.trace_id <> OLD.trace_id
    OR NEW.run_id <> OLD.run_id
BEGIN
    SELECT RAISE(ABORT, 'v3 audit stream identity is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_stream_heads_initial
BEFORE INSERT ON v3_audit_stream_heads
FOR EACH ROW
WHEN NEW.current_sequence <> 0 OR NEW.current_event_id IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'v3 audit stream head must begin empty');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_stream_heads_advance
BEFORE UPDATE ON v3_audit_stream_heads
FOR EACH ROW
WHEN
    NEW.current_sequence <> OLD.current_sequence + 1
    OR NEW.current_event_id IS NULL
    OR NOT EXISTS (
        SELECT 1
        FROM v3_audit_events AS event
        WHERE event.stream_id = OLD.stream_id
          AND event.sequence = NEW.current_sequence
          AND event.event_id = NEW.current_event_id
          AND (
              (
                  OLD.current_sequence = 0
                  AND event.previous_event_id IS NULL
              )
              OR event.previous_event_id = OLD.current_event_id
          )
    )
BEGIN
    SELECT RAISE(ABORT, 'v3 audit stream head must advance exactly once');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_stream_heads_immutable_delete
BEFORE DELETE ON v3_audit_stream_heads
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 audit stream heads cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_events_append
BEFORE INSERT ON v3_audit_events
FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1
    FROM v3_audit_stream_heads AS head
    WHERE head.stream_id = NEW.stream_id
      AND head.tenant_id = NEW.tenant_id
      AND head.repository_id = NEW.repository_id
      AND head.session_id = NEW.session_id
      AND head.trace_id = NEW.trace_id
      AND head.run_id = NEW.run_id
      AND NEW.sequence = head.current_sequence + 1
      AND (
          (
              head.current_sequence = 0
              AND NEW.previous_event_id IS NULL
          )
          OR NEW.previous_event_id = head.current_event_id
      )
)
BEGIN
    SELECT RAISE(ABORT, 'v3 audit event is not the next stream event');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_events_immutable_update
BEFORE UPDATE ON v3_audit_events
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 audit events are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_audit_events_immutable_delete
BEFORE DELETE ON v3_audit_events
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 audit events cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_recovery_actions_immutable_update
BEFORE UPDATE ON v3_recovery_actions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 recovery actions are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_recovery_actions_immutable_delete
BEFORE DELETE ON v3_recovery_actions
FOR EACH ROW
BEGIN
    SELECT RAISE(ABORT, 'v3 recovery actions cannot be deleted');
END;
-- END COMPONENT audit

-- BEGIN COMPONENT event-ledger
CREATE TABLE IF NOT EXISTS trace_backed_memory_v3_event_ledger_schema (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version = 1),
    contract_version TEXT NOT NULL CHECK (
        contract_version = 'tbm.event-ledger-port.v1'
    )
);

INSERT OR IGNORE INTO trace_backed_memory_v3_event_ledger_schema (
    singleton,
    schema_version,
    contract_version
) VALUES (1, 1, 'tbm.event-ledger-port.v1');

CREATE TABLE IF NOT EXISTS v3_event_ledger_global_head (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    current_global_position INTEGER NOT NULL CHECK (
        current_global_position >= 0
    ),
    current_event_id TEXT,
    current_event_sha256 TEXT,
    CHECK (
        (current_global_position = 0 AND current_event_id IS NULL
            AND current_event_sha256 IS NULL)
        OR
        (current_global_position > 0 AND current_event_id IS NOT NULL
            AND current_event_sha256 IS NOT NULL)
    )
);

INSERT OR IGNORE INTO v3_event_ledger_global_head (
    singleton,
    current_global_position,
    current_event_id,
    current_event_sha256
) VALUES (1, 0, NULL, NULL);

CREATE TABLE IF NOT EXISTS v3_event_ledger_stream_heads (
    partition_sha256 TEXT NOT NULL,
    stream_id TEXT NOT NULL,
    organization_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    repository_id TEXT NOT NULL,
    environment_id TEXT NOT NULL,
    current_stream_version INTEGER NOT NULL CHECK (
        current_stream_version >= 0
    ),
    current_event_id TEXT,
    current_event_sha256 TEXT,
    PRIMARY KEY (partition_sha256, stream_id),
    CHECK (
        (current_stream_version = 0 AND current_event_id IS NULL
            AND current_event_sha256 IS NULL)
        OR
        (current_stream_version > 0 AND current_event_id IS NOT NULL
            AND current_event_sha256 IS NOT NULL)
    )
);

CREATE TABLE IF NOT EXISTS v3_event_ledger_events (
    event_id TEXT PRIMARY KEY,
    event_sha256 TEXT NOT NULL UNIQUE,
    partition_sha256 TEXT NOT NULL,
    organization_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    repository_id TEXT NOT NULL,
    environment_id TEXT NOT NULL,
    stream_id TEXT NOT NULL,
    stream_version INTEGER NOT NULL CHECK (stream_version >= 1),
    global_position INTEGER NOT NULL UNIQUE CHECK (global_position >= 1),
    previous_stream_event_sha256 TEXT,
    classification TEXT NOT NULL CHECK (
        classification IN ('public', 'internal', 'confidential', 'restricted')
    ),
    artifact_ref_count INTEGER NOT NULL CHECK (
        artifact_ref_count BETWEEN 0 AND 128
    ),
    canonical_event TEXT NOT NULL COLLATE BINARY CHECK (
        length(CAST(canonical_event AS BLOB)) BETWEEN 2 AND 1048576
        AND json_valid(canonical_event)
    ),
    UNIQUE (partition_sha256, stream_id, stream_version),
    FOREIGN KEY (partition_sha256, stream_id)
        REFERENCES v3_event_ledger_stream_heads (
            partition_sha256,
            stream_id
        )
        DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX IF NOT EXISTS v3_event_ledger_events_partition_global
ON v3_event_ledger_events (partition_sha256, global_position);

CREATE INDEX IF NOT EXISTS v3_event_ledger_events_partition_stream
ON v3_event_ledger_events (
    partition_sha256,
    stream_id,
    stream_version
);

CREATE TABLE IF NOT EXISTS v3_event_ledger_artifacts (
    event_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    artifact_id TEXT NOT NULL,
    content_sha256 TEXT NOT NULL,
    media_type TEXT NOT NULL,
    size_bytes INTEGER NOT NULL CHECK (
        size_bytes BETWEEN 0 AND 67108864
    ),
    classification TEXT NOT NULL CHECK (
        classification IN ('public', 'internal', 'confidential', 'restricted')
    ),
    retention_policy_id TEXT NOT NULL,
    encryption_key_id TEXT,
    availability TEXT NOT NULL CHECK (
        availability IN ('available', 'erased', 'external', 'unavailable')
    ),
    descriptor TEXT NOT NULL COLLATE BINARY CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 2 AND 16384
        AND json_valid(descriptor)
    ),
    PRIMARY KEY (event_id, ordinal),
    UNIQUE (event_id, artifact_id),
    FOREIGN KEY (event_id)
        REFERENCES v3_event_ledger_events (event_id)
        DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS v3_event_ledger_idempotency (
    partition_sha256 TEXT NOT NULL,
    idempotency_key_sha256 TEXT NOT NULL,
    command_sha256 TEXT NOT NULL,
    request_sha256 TEXT NOT NULL,
    stream_id TEXT NOT NULL,
    previous_stream_version INTEGER NOT NULL CHECK (
        previous_stream_version >= 0
    ),
    current_stream_version INTEGER NOT NULL CHECK (
        current_stream_version > previous_stream_version
    ),
    first_global_position INTEGER NOT NULL CHECK (
        first_global_position >= 1
    ),
    last_global_position INTEGER NOT NULL CHECK (
        last_global_position >= first_global_position
    ),
    event_sha256s_json TEXT NOT NULL COLLATE BINARY CHECK (
        length(CAST(event_sha256s_json AS BLOB)) BETWEEN 4 AND 16384
        AND json_valid(event_sha256s_json)
    ),
    receipt_sha256 TEXT NOT NULL,
    PRIMARY KEY (partition_sha256, idempotency_key_sha256)
);

CREATE TABLE IF NOT EXISTS v3_event_ledger_checkpoints (
    projection_name TEXT NOT NULL CHECK (
        length(CAST(projection_name AS BLOB)) BETWEEN 1 AND 128
    ),
    projection_version INTEGER NOT NULL CHECK (projection_version >= 1),
    partition_sha256 TEXT NOT NULL CHECK (
        length(partition_sha256) = 71
        AND substr(partition_sha256, 1, 7) = 'sha256:'
        AND substr(partition_sha256, 8) NOT GLOB '*[^0-9a-f]*'
    ),
    global_position INTEGER NOT NULL CHECK (global_position >= 0),
    state_sha256 TEXT NOT NULL CHECK (
        length(state_sha256) = 71
        AND substr(state_sha256, 1, 7) = 'sha256:'
        AND substr(state_sha256, 8) NOT GLOB '*[^0-9a-f]*'
    ),
    descriptor TEXT NOT NULL COLLATE BINARY CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 2 AND 1048576
        AND json_valid(descriptor)
    ),
    PRIMARY KEY (
        projection_name,
        projection_version,
        partition_sha256,
        global_position
    )
);

CREATE TABLE IF NOT EXISTS v3_event_ledger_projection_activations (
    projection_name TEXT NOT NULL CHECK (
        length(CAST(projection_name AS BLOB)) BETWEEN 1 AND 128
    ),
    partition_sha256 TEXT NOT NULL CHECK (
        length(partition_sha256) = 71
        AND substr(partition_sha256, 1, 7) = 'sha256:'
        AND substr(partition_sha256, 8) NOT GLOB '*[^0-9a-f]*'
    ),
    head_version INTEGER NOT NULL CHECK (head_version >= 1),
    target_build_id TEXT NOT NULL CHECK (
        length(target_build_id) = 71
        AND substr(target_build_id, 1, 7) = 'sha256:'
        AND substr(target_build_id, 8) NOT GLOB '*[^0-9a-f]*'
    ),
    previous_build_id TEXT CHECK (
        previous_build_id IS NULL OR (
            length(previous_build_id) = 71
            AND substr(previous_build_id, 1, 7) = 'sha256:'
            AND substr(previous_build_id, 8) NOT GLOB '*[^0-9a-f]*'
        )
    ),
    operation TEXT NOT NULL CHECK (operation IN ('activate', 'rollback')),
    activation_sha256 TEXT NOT NULL UNIQUE CHECK (
        length(activation_sha256) = 71
        AND substr(activation_sha256, 1, 7) = 'sha256:'
        AND substr(activation_sha256, 8) NOT GLOB '*[^0-9a-f]*'
    ),
    descriptor TEXT NOT NULL COLLATE BINARY CHECK (
        length(CAST(descriptor AS BLOB)) BETWEEN 2 AND 1048576
        AND json_valid(descriptor)
    ),
    PRIMARY KEY (projection_name, partition_sha256, head_version)
);

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_schema_immutable_update
BEFORE UPDATE ON trace_backed_memory_v3_event_ledger_schema
BEGIN
    SELECT RAISE(ABORT, 'event ledger schema metadata is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_schema_immutable_delete
BEFORE DELETE ON trace_backed_memory_v3_event_ledger_schema
BEGIN
    SELECT RAISE(ABORT, 'event ledger schema metadata cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_projection_activations_validate_insert
BEFORE INSERT ON v3_event_ledger_projection_activations
WHEN (
    NEW.head_version = 1
    AND (
        NEW.previous_build_id IS NOT NULL
        OR EXISTS (
            SELECT 1 FROM v3_event_ledger_projection_activations
            WHERE projection_name = NEW.projection_name
              AND partition_sha256 = NEW.partition_sha256
        )
    )
) OR (
    NEW.head_version > 1
    AND NOT EXISTS (
        SELECT 1 FROM v3_event_ledger_projection_activations
        WHERE projection_name = NEW.projection_name
          AND partition_sha256 = NEW.partition_sha256
          AND head_version = NEW.head_version - 1
          AND target_build_id = NEW.previous_build_id
    )
)
BEGIN
    SELECT RAISE(ABORT, 'projection activation does not advance its head');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_projection_activations_immutable_update
BEFORE UPDATE ON v3_event_ledger_projection_activations
BEGIN
    SELECT RAISE(ABORT, 'projection activation rows are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_projection_activations_immutable_delete
BEFORE DELETE ON v3_event_ledger_projection_activations
BEGIN
    SELECT RAISE(ABORT, 'projection activation rows cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_global_head_validate_insert
BEFORE INSERT ON v3_event_ledger_global_head
WHEN NEW.singleton <> 1 OR NEW.current_global_position <> 0
    OR NEW.current_event_id IS NOT NULL
    OR NEW.current_event_sha256 IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'event ledger global head must start empty');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_global_head_advance
BEFORE UPDATE ON v3_event_ledger_global_head
BEGIN
    SELECT CASE WHEN
        NEW.singleton <> OLD.singleton
        OR NEW.current_global_position <> OLD.current_global_position + 1
        OR NOT EXISTS (
            SELECT 1
            FROM v3_event_ledger_events AS event
            WHERE event.global_position = NEW.current_global_position
              AND event.event_id = NEW.current_event_id
              AND event.event_sha256 = NEW.current_event_sha256
        )
    THEN RAISE(ABORT, 'event ledger global head advance is invalid') END;
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_global_head_no_delete
BEFORE DELETE ON v3_event_ledger_global_head
BEGIN
    SELECT RAISE(ABORT, 'event ledger global head cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_stream_heads_validate_insert
BEFORE INSERT ON v3_event_ledger_stream_heads
WHEN NEW.current_stream_version <> 0 OR NEW.current_event_id IS NOT NULL
    OR NEW.current_event_sha256 IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'event ledger stream head must start empty');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_stream_heads_identity_immutable
BEFORE UPDATE ON v3_event_ledger_stream_heads
WHEN NEW.partition_sha256 <> OLD.partition_sha256
    OR NEW.stream_id <> OLD.stream_id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.tenant_id <> OLD.tenant_id
    OR NEW.repository_id <> OLD.repository_id
    OR NEW.environment_id <> OLD.environment_id
BEGIN
    SELECT RAISE(ABORT, 'event ledger stream identity is immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_stream_heads_advance
BEFORE UPDATE ON v3_event_ledger_stream_heads
BEGIN
    SELECT CASE WHEN
        NEW.current_stream_version <> OLD.current_stream_version + 1
        OR NOT EXISTS (
            SELECT 1
            FROM v3_event_ledger_events AS event
            WHERE event.partition_sha256 = NEW.partition_sha256
              AND event.stream_id = NEW.stream_id
              AND event.stream_version = NEW.current_stream_version
              AND event.event_id = NEW.current_event_id
              AND event.event_sha256 = NEW.current_event_sha256
        )
    THEN RAISE(ABORT, 'event ledger stream head advance is invalid') END;
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_stream_heads_no_delete
BEFORE DELETE ON v3_event_ledger_stream_heads
BEGIN
    SELECT RAISE(ABORT, 'event ledger stream head cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_events_validate_insert
BEFORE INSERT ON v3_event_ledger_events
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM v3_event_ledger_stream_heads AS head
        WHERE head.partition_sha256 = NEW.partition_sha256
          AND head.stream_id = NEW.stream_id
          AND head.organization_id = NEW.organization_id
          AND head.tenant_id = NEW.tenant_id
          AND head.repository_id = NEW.repository_id
          AND head.environment_id = NEW.environment_id
          AND head.current_stream_version = NEW.stream_version - 1
          AND head.current_event_sha256 IS NEW.previous_stream_event_sha256
    ) THEN RAISE(ABORT, 'event does not extend the current stream head') END;
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM v3_event_ledger_global_head AS head
        WHERE head.singleton = 1
          AND head.current_global_position = NEW.global_position - 1
    ) THEN RAISE(ABORT, 'event does not extend the global ledger head') END;
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_events_immutable_update
BEFORE UPDATE ON v3_event_ledger_events
BEGIN
    SELECT RAISE(ABORT, 'event ledger events are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_events_immutable_delete
BEFORE DELETE ON v3_event_ledger_events
BEGIN
    SELECT RAISE(ABORT, 'event ledger events cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_artifacts_validate_insert
BEFORE INSERT ON v3_event_ledger_artifacts
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM v3_event_ledger_events AS event
        WHERE event.event_id = NEW.event_id
          AND NEW.ordinal < event.artifact_ref_count
    ) THEN RAISE(ABORT, 'event artifact ordinal is outside the event descriptor') END;
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_artifacts_immutable_update
BEFORE UPDATE ON v3_event_ledger_artifacts
BEGIN
    SELECT RAISE(ABORT, 'event artifact descriptors are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_artifacts_immutable_delete
BEFORE DELETE ON v3_event_ledger_artifacts
BEGIN
    SELECT RAISE(ABORT, 'event artifact descriptors cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_idempotency_immutable_update
BEFORE UPDATE ON v3_event_ledger_idempotency
BEGIN
    SELECT RAISE(ABORT, 'event ledger idempotency records are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_idempotency_immutable_delete
BEFORE DELETE ON v3_event_ledger_idempotency
BEGIN
    SELECT RAISE(ABORT, 'event ledger idempotency records cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_checkpoints_immutable_update
BEFORE UPDATE ON v3_event_ledger_checkpoints
BEGIN
    SELECT RAISE(ABORT, 'event ledger checkpoints are immutable');
END;

CREATE TRIGGER IF NOT EXISTS v3_event_ledger_checkpoints_immutable_delete
BEFORE DELETE ON v3_event_ledger_checkpoints
BEGIN
    SELECT RAISE(ABORT, 'event ledger checkpoints cannot be deleted');
END;
